    steps: [
      'Rinse the rice until the water runs mostly clear. Add it to a saucepan with 280 ml water and a pinch of salt. Bring to the boil, cover and simmer gently for 12 minutes, then remove from the heat and leave covered for 5 minutes.',
      'Slice the pepper and carrot thinly and crush the garlic. Heat half the oil in a large frying pan, cook the vegetables for 5 minutes until softened, then tip onto a clean plate.',
      'Add the remaining oil to the pan and fry the diced chicken with the ginger and garlic for 8 to 12 minutes, stirring frequently. Check the largest piece has reached 75°C for 30 seconds and keep raw-chicken utensils separate.',
      'Return the vegetables to the pan. Stir in the soy sauce and honey, simmer for 2 minutes until coated and piping hot, then serve over the rice with the sesame seeds sprinkled on top.',
    ],
