    steps: [
      'Chop the potatoes into even pieces, put them in a saucepan of cold salted water and boil gently for 15 to 20 minutes until soft. Wash the leek thoroughly, then slice it and the carrot.',
      'Heat the olive oil in a frying pan. Cook the leek and carrot for 7 minutes until tender, add the crushed garlic and stir for another minute. Move the vegetables to one side of the pan.',
      'Add the chicken breasts and cook over medium heat for approximately 6 to 8 minutes each side, adjusting for thickness. Check 75°C for 30 seconds in the thickest part. Stir the crème fraîche and mustard into the vegetables and heat gently until hot throughout.',
      'Drain the potatoes, then mash with the butter and half the black pepper. Season the chicken sauce with the remaining pepper and divide the mash, vegetables and fully cooked chicken between two plates.',
    ],
