    steps: [
      'Dice the courgette and onion, crush the garlic and shred the basil. Warm the olive oil in a wide saucepan and cook the onion and courgette for 5 minutes, stirring regularly.',
      'Add the diced chicken, season with salt and pepper and fry for 6 minutes. Wash any equipment that touched raw chicken before using it again.',
      'Stir in the crushed garlic, orzo, passata and 350 ml water. Cover loosely and simmer gently for 12 to 15 minutes, stirring and adding a splash of hot water only if necessary to prevent sticking. Confirm the largest chicken piece reaches 75°C for 30 seconds and the orzo is tender.',
      'Take the pan off the heat. Stir through the grated hard cheese and basil until combined, then divide the hot chicken and tomato orzo between two bowls.',
    ],
