    steps: [
      'Heat the oven to 200°C fan. Cut the pepper and onion into strips and toss with half the oil and half the salt. Roast on a baking tray for 15 to 20 minutes until softened.',
      'Slice the chicken into even strips on a separate board and coat them with the harissa paste and remaining oil. Arrange on another tray and bake for approximately 15 to 20 minutes, stirring once.',
      'Check the thickest chicken strip reaches 75°C for 30 seconds before removing it from the oven. Wash hands and equipment that touched raw chicken and avoid using its utensils to serve.',
      'Shred and wash the lettuce. Mix the yoghurt with lemon juice and remaining salt, warm the tortillas according to the packet, then fill each with cooked chicken, roasted vegetables, lettuce and lemon yoghurt.',
    ],
