    steps: [
      'Rinse the rice and put it in a saucepan with 280 ml water and half the salt. Bring to the boil, cover and simmer gently for 12 minutes, then leave covered off the heat for 5 minutes.',
      'Cut the bell pepper into thin strips and finely chop the red onion and garlic. Heat the oil in a deep pan and soften the onion and pepper for 6 minutes.',
      'Add the beef mince and cook, breaking up the lumps, for 8 to 10 minutes until fully browned. Stir in the garlic and cumin and cook for another minute, taking care that the mince reaches 75°C for 30 seconds in the centre.',
      'Pour in the passata, season with the remaining salt and pepper and simmer for 5 minutes until piping hot and thickened. Serve the beef and pepper sauce over the fluffy rice.',
    ],
