    steps: [
      'Rinse the jasmine rice and bring to a gentle simmer with 280 ml water. Cover and cook for 12 minutes, then leave off the heat, still covered, for another 5 minutes.',
      'Grate the carrot and slice the courgette into small half-moons. Heat half the oil in a frying pan and stir-fry both vegetables for 5 minutes until tender. Move them to a clean bowl.',
      'Heat the remaining oil in the pan, add the beef mince, ginger and crushed garlic, and cook for 8 to 10 minutes while breaking up the mince. Confirm 75°C for 30 seconds in its centre.',
      'Add the cooked vegetables, soy sauce and honey to the beef. Cook together for 2 more minutes until bubbling, then spoon onto the rice and scatter over the sesame seeds.',
    ],
