    steps: [
      'Heat the oven to 200°C fan. Finely chop half the red onion and crush one garlic clove. Mix the onion and garlic with the beef mince, cumin, paprika and half the salt, then shape into eight even koftas using clean hands.',
      'Arrange the koftas on a lined tray and bake for 15 to 20 minutes, turning once. Check the thickest reaches 75°C for 30 seconds before serving and wash all equipment that touched raw mince.',
      'Slice the courgette and the remaining red onion. Toss with the olive oil and roast on a second tray for around 18 minutes until tender. Meanwhile, cover the couscous with 160 ml boiling water for 8 minutes, then fluff it.',
      'Crush the remaining garlic clove. Mix it into the yoghurt with lemon juice and the remaining salt. Toss the roasted vegetables into the couscous and serve with the cooked koftas and lemon yoghurt.',
    ],
