    steps: [
      'Heat the oven to 210°C fan. Scrub the potatoes, prick them with a fork and rub with 5 ml of the olive oil. Bake for 40 to 50 minutes until the centres are completely soft.',
      'Dice the onion, slice the mushrooms and crush the garlic. Warm the remaining 10 ml olive oil in a deep frying pan, soften the onion and mushrooms for 6 minutes and stir in the garlic for a further minute.',
      'Add the beef mince and cook for approximately 9 to 12 minutes, breaking it up and stirring frequently. Check the thickest clump reaches 75°C for 30 seconds. Stir in the crème fraîche, mustard, salt and pepper and heat gently until piping hot.',
      'Trim the green beans and boil in fresh water for 5 to 7 minutes until tender and thoroughly cooked. Drain them, split the baked potatoes and spoon in the creamy peppercorn beef. Serve with the hot green beans.',
    ],
