    steps: [
      'Heat the oven to 200°C fan. Halve the courgettes lengthways and scoop out a shallow channel, chopping the removed flesh finely. Brush the baking tray with 5 ml olive oil and place the hollowed halves on it.',
      'Rinse the rice and cook covered with 200 ml water for 12 minutes. Let it stand off the heat for 5 minutes. Meanwhile, chop the onion and garlic.',
      'Warm the remaining 10 ml olive oil in a pan, soften the onion and chopped courgette for 5 minutes, then add the beef mince, cumin and garlic. Cook for 9 to 12 minutes until fully cooked to 75°C for 30 seconds. Stir in the passata, salt and cooked rice.',
      'Pile the hot beef rice mixture into the courgette halves and sprinkle with grated Cheddar. Bake for 15 to 18 minutes until the courgettes are soft and the filling is piping hot throughout, then serve.',
    ],
