    steps: [
      'Bring a saucepan of water to the boil, then cook the egg noodle nests following the packet instructions. Drain well. Peel the carrot and cut it and the pepper into narrow strips.',
      'Heat half the oil in a frying pan and stir-fry the carrot and pepper for 5 minutes until tender. Tip into a clean bowl.',
      'Heat the remaining oil in the pan and add the pork mince with ginger and crushed garlic. Break it into small pieces and cook for about 10 minutes, checking that it reaches 75°C for 30 seconds and has no pink meat remaining.',
      'Return the vegetables to the pan and stir through the soy sauce, honey and black pepper. Cook for 2 minutes until bubbling, toss with the drained noodles and serve with lime juice squeezed over.',
    ],
