    steps: [
      'Bring a large pan of water to the boil with half the salt. Mix the pork mince with breadcrumbs, oregano and half the black pepper, then form ten evenly sized meatballs. Wash your hands and the board after handling raw pork.',
      'Heat the olive oil in a deep frying pan, add the meatballs and brown gently for 5 minutes, turning regularly. Remove to a clean plate while you soften the chopped onion in the same pan for 4 minutes.',
      'Add the crushed garlic, passata, remaining salt and meatballs back to the pan. Cover and simmer for 15 to 18 minutes, stirring gently, until the meatballs are fully cooked to 75°C for 30 seconds.',
      'Cook the rigatoni following its packet instructions, drain and fold into the hot tomato and pork sauce. Scatter over the grated hard cheese and remaining pepper and serve.',
    ],
