    steps: [
      'Heat the oven to 200°C fan. Cut the potatoes into 2 cm pieces and slice the apple and red onion. Coat the potatoes and onion with half the oil, half the salt and oregano, then roast for 25 minutes.',
      'Mix the pork mince with the wholegrain mustard, remaining salt and black pepper. Shape into six small patties and wash your hands and any raw-meat equipment before touching the prepared vegetables.',
      'Arrange the patties on a separate baking tray and cook in the oven for approximately 18 to 22 minutes, turning once. Check the middle reaches 75°C for 30 seconds. Add the apple slices to the potato tray for its final 10 minutes.',
      'Mix the yoghurt with a squeeze of lemon and the remaining olive oil. Serve the hot pork patties beside the golden potatoes, softened apple and onion, with the lemon yoghurt.',
    ],
