    steps: [
      'Heat the oven to 200°C fan. Halve the tomatoes and slice the courgette. Toss with half the olive oil and roast for 18 to 20 minutes until soft and lightly browned.',
      'Bring a large saucepan of salted water to the boil. Cook the spaghetti according to its packet instructions until tender, reserving a small cup of pasta water before draining.',
      'Heat the remaining oil in a clean frying pan, add crushed garlic and chilli flakes for 30 seconds, then add the prawns. Cook according to the prawn pack instructions, stirring until they are opaque and thoroughly cooked throughout. Never rely on colour alone for raw shellfish doneness.',
      'Add the roasted vegetables and drained spaghetti to the hot pan, toss with a splash of pasta water, lemon juice and chopped parsley and season with pepper. Serve immediately with the cooked prawns.',
    ],
