    steps: [
      'Heat the oven to 200°C fan. Scrub the potatoes and cut into bite-sized pieces. Toss with 5 ml olive oil, spread on a baking tray and roast for 25 to 30 minutes until golden and soft, turning once.',
      'Core and thinly slice the apple and red onion. Heat 5 ml olive oil in a frying pan, soften the onion for 4 minutes, then add the apple for 3 minutes. Stir in the spinach just until wilted and transfer to a clean bowl.',
      'Pat the halloumi dry and cut it into eight slices. Add the remaining 5 ml olive oil to the frying pan and fry the halloumi for 2 to 3 minutes on each side until golden and piping hot.',
      'Whisk the wholegrain mustard with lemon juice and black pepper. Toss the warm roast potatoes with the apple, onion and spinach mixture, drizzle over the dressing and top with the hot halloumi slices.',
    ],
