    steps: [
      'Peel the sweet potato and chop into small cubes, rinse the lentils thoroughly and finely dice the onion. Crush the garlic and heat the vegetable oil in a deep saucepan.',
      'Cook the onion for 4 minutes until soft, then stir in the garlic, turmeric and cumin for 1 minute. Add the sweet potato, lentils and chopped tomatoes.',
      'Pour in the coconut milk and 400 ml water. Bring to a gentle simmer, cover partly and cook for 22 to 28 minutes, stirring regularly, until the lentils and sweet potato are completely tender. Add more hot water only if the dhal becomes too thick before the lentils soften.',
      'Stir the spinach through the hot dhal and cook until fully wilted. Season with salt, check the lentils are soft all the way through and divide into two bowls.',
    ],
