    steps: [
      'Rinse the rice and place in a saucepan with 280 ml water and half the salt. Cover, simmer gently for 12 minutes and rest with the lid on for 5 minutes.',
      'Slice the mushrooms and onion, crush the garlic and drain the butter beans. Heat the oil in a large frying pan and cook the mushrooms and onion for 8 minutes until the moisture has mostly evaporated.',
      'Stir in the garlic, paprika and tomato purée for 1 minute, then add the beans. Cook gently for 4 minutes until the beans are piping hot before lowering the heat.',
      'Stir in the crème fraîche without bringing it to a vigorous boil. Season with the remaining salt and pepper, simmer for 2 minutes to heat through and serve the creamy mushroom sauce over the rice.',
    ],
