    steps: [
      'Heat the oven to 200°C fan. Cut the aubergine into bite-sized cubes, toss with half the olive oil, oregano and half the salt and roast on a baking tray for 20 minutes until soft.',
      'Drain and rinse the chickpeas. Finely chop the onion and garlic, then soften the onion in the remaining olive oil for 5 minutes. Add the garlic for 1 minute, followed by the passata and chickpeas. Add the remaining salt and black pepper and simmer for 6 minutes until the chickpeas are piping hot.',
      'Transfer the roasted aubergine to an ovenproof dish and spoon over the chickpea tomato sauce. Tear the mozzarella into small pieces, scatter over the sauce and finish with the grated hard cheese.',
      'Bake the gratin for 12 to 15 minutes until the cheese is golden and the centre is piping hot. Warm the ciabatta according to the packet instructions and serve alongside the gratin.',
    ],
