    steps: [
      'Rinse the basmati rice and add to a saucepan with 280 ml water and half the salt. Cover and simmer for 12 minutes, then rest off the heat with the lid on for another 5 minutes.',
      'Slice the bell pepper and red onion, grate the carrot and drain the black beans. Heat the oil in a large frying pan and cook the pepper, onion and carrot for 6 minutes until softened.',
      'Stir in the cumin and smoked paprika for 1 minute. Add the drained beans and passata and simmer for 8 minutes until thickened and piping hot all the way through.',
      'Squeeze the lime over the vegetable and bean mixture, season with the remaining salt and divide between bowls filled with fluffy rice.',
    ],
